  T3[0] = Q(["Why do low-pressure chillers need a purge unit?", "¿Por qué los chillers de baja presión necesitan una unidad de purga?"],
    [["Parts run below atmospheric pressure, so leaks pull air and moisture in", "Partes trabajan bajo presión atmosférica, así que las fugas meten aire y humedad"], ["To add oil", "Para agregar aceite"], ["To raise head pressure", "Para subir la presión de descarga"], ["To vent refrigerant on purpose", "Para ventear refrigerante a propósito"]], 0,
    ["The evaporator side runs in a vacuum. Leaks pull air in instead of letting refrigerant out; the purge removes those non-condensables.", "El lado del evaporador trabaja en vacío. Las fugas meten aire en vez de sacar refrigerante; la purga quita esos no condensables."], "Service practice");
